(471576, 45172, 10848, '<td valign="top">Beautiful shot, I like the way you captured this shot with an upward angle, the angle really adds to this shot.good job</td>', 'Beautiful shot, I like the way you captured this shot with an upward angle, the angle really adds to this shot.good job', '2003-11-03 21:49:43.000000', NULL, 1),
