(472539, 44619, 4767, '<td valign="top">OH yeah!  Wish it were my shot!  Nice nice photo!</td>', 'OH yeah!  Wish it were my shot!  Nice nice photo!', '2003-11-04 21:26:34.000000', NULL, 1),
