(472547, 44921, 4767, '<td valign="top">And not just infinite, DELICIOUS infinity!  Cadbury''s would make it infinitely enjoyable!</td>', 'And not just infinite, DELICIOUS infinity!  Cadbury''s would make it infinitely enjoyable!', '2003-11-04 21:40:11.000000', NULL, 1),
(472548, 45101, 4767, '<td valign="top">THIS is why I love DPC.  A photo that makes me stand in awe!  EXTRAORDINARY image!</td>', 'THIS is why I love DPC.  A photo that makes me stand in awe!  EXTRAORDINARY image!', '2003-11-04 21:44:06.000000', NULL, 1),
(472549, 44999, 13390, '<td valign="top">Beautiful Focus and Colors!</td>', 'Beautiful Focus and Colors!', '2003-11-04 21:46:13.000000', NULL, 1),
(472551, 44981, 4767, '<td valign="top">Who CARES about the stars?  GREAT aurora shot!</td>', 'Who CARES about the stars?  GREAT aurora shot!', '2003-11-04 21:47:23.000000', NULL, 1),
(472559, 45126, 4767, '<td valign="top">My wife said to add another point for creativity.  So I did.  (1492 - Columbus sailed...)  nice touch!</td>', 'My wife said to add another point for creativity.  So I did.  (1492 - Columbus sailed...)  nice touch!', '2003-11-04 21:54:49.000000', NULL, 1),
