(472568, 45157, 11134, '<td valign="top">feels a bit too dark to me, considering the possibilities of colors in a vineyard.  nice angle though</td>', 'feels a bit too dark to me, considering the possibilities of colors in a vineyard.  nice angle though', '2003-11-04 22:00:03.000000', NULL, 1),
(472572, 45012, 11134, '<td valign="top">beautiful colors, very creative, nice angle, altogether well done.  I like that the background isn''t just static.  10</td>', 'beautiful colors, very creative, nice angle, altogether well done.  I like that the background isn''t just static.  10', '2003-11-04 22:03:43.000000', NULL, 1),
(472582, 45135, 12611, '<td valign="top">Nice gun-metal purple color; and youv''e used a lens to take a picture of a lens, very nice, and infinite</td>', 'Nice gun-metal purple color; and youv''e used a lens to take a picture of a lens, very nice, and infinite', '2003-11-04 22:20:23.000000', NULL, 1),
(472583, 44981, 12611, '<td valign="top">If this is real, and I have no reason to believe otherwise, its fantastic. Perhaps the number of stars are infinite...</td>', 'If this is real, and I have no reason to believe otherwise, its fantastic. Perhaps the number of stars are infinite...', '2003-11-04 22:22:56.000000', NULL, 1),
(472585, 45087, 12611, '<td valign="top">I love the feeling of motion in this shot. Great lighting, really terrific</td>', 'I love the feeling of motion in this shot. Great lighting, really terrific', '2003-11-04 22:24:36.000000', NULL, 1),
(472586, 44900, 12611, '<td valign="top">I''m dizzy... you are pretty creative.<br/></td>', 'I''m dizzy... you are pretty creative.', '2003-11-04 22:25:29.000000', NULL, 1),
(472590, 45009, 12611, '<td valign="top">Nice movement, good depth, good use of black and white. I don''t like the people in the shot, but its still great.</td>', 'Nice movement, good depth, good use of black and white. I don''t like the people in the shot, but its still great.', '2003-11-04 22:28:08.000000', NULL, 1),
(472593, 44631, 12611, '<td valign="top">interesting idea; nice sepia color</td>', 'interesting idea; nice sepia color', '2003-11-04 22:29:26.000000', NULL, 1),
(472595, 45162, 12611, '<td valign="top">Beautiful movement and focus going on here; I love the time of day you took this; one criticism is that the "pipeline" has an uber metallic look to it that is distracting.</td>', 'Beautiful movement and focus going on here; I love the time of day you took this; one criticism is that the "pipeline" has an uber metallic look to it that is distracting.', '2003-11-04 22:32:03.000000', NULL, 1),
(472599, 45102, 12611, '<td valign="top">Nice shot; there is a great prismic color pattern going on here and you really know what you are doing. nice cropping too, although the photo does get a bit "noisy" or over sharp/grainy in the background center.</td>', 'Nice shot; there is a great prismic color pattern going on here and you really know what you are doing. nice cropping too, although the photo does get a bit "noisy" or over sharp/grainy in the background center.', '2003-11-04 22:34:34.000000', NULL, 1),
(472603, 44957, 12611, '<td valign="top">I love the face on the nautilus; and nice shine; I don''t like the blue place mat underneath, it is a color distraction- but once again- better thaan I can do</td>', 'I love the face on the nautilus; and nice shine; I don''t like the blue place mat underneath, it is a color distraction- but once again- better thaan I can do', '2003-11-04 22:37:06.000000', NULL, 1),
(472606, 44958, 12611, '<td valign="top">Don''t use the name in the title; use a thesaurus instead. Nice panoramic shot though, no smellyness here. at least your shot doesn''t stink! next time, if you want to keep the  title, try the condom isle :)</td>', 'Don''t use the name in the title; use a thesaurus instead. Nice panoramic shot though, no smellyness here. at least your shot doesn''t stink! next time, if you want to keep the  title, try the condom isle :)', '2003-11-04 22:39:22.000000', NULL, 1),
(472613, 45106, 3665, '<td valign="top">What exactly is this?</td>', 'What exactly is this?', '2003-11-04 22:49:22.000000', NULL, 1),
(472615, 45087, 3665, '<td valign="top">Looks like many weeds to me.... not just one tiny one.</td>', 'Looks like many weeds to me.... not just one tiny one.', '2003-11-04 22:55:31.000000', NULL, 1),
(472619, 45088, 10686, '<td valign="top">the un-level horizon and the powerlines kill this shot for me</td>', 'the un-level horizon and the powerlines kill this shot for me', '2003-11-04 22:59:34.000000', NULL, 1),
(472621, 44947, 10686, '<td valign="top">Great colors</td>', 'Great colors', '2003-11-04 23:00:21.000000', NULL, 1),
(472634, 44578, 3102, '<td valign="top">Nice clarity!  The colors of the individual kernals are quite unique and appealing, too.</td>', 'Nice clarity!  The colors of the individual kernals are quite unique and appealing, too.', '2003-11-04 23:30:18.000000', NULL, 1),
(472642, 44904, 6804, '<td valign="top">This is just a cool shot !<br/>This is defiantly a 10 from me. I like the straight on shot with the lead lines into the upper third. The shot has a lot of interest. I stare at it trying to figure out if these are toys or statues at life size. Awesome shot.<br/></td>', 'This is just a cool shot !This is defiantly a 10 from me. I like the straight on shot with the lead lines into the upper third. The shot has a lot of interest. I stare at it trying to figure out if these are toys or statues at life size. Awesome shot.', '2003-11-04 23:39:54.000000', NULL, 1),
(472651, 45136, 6804, '<td valign="top">Nicely done. The color is perfect and I like the addition and position of the flowers. The string was a little distracting to me at first, but after reading the title, I see they must be setting alignment for yet another plot. What an honor, what a disgrace and what a way to capture the emotion. One of my top picks  9</td>', 'Nicely done. The color is perfect and I like the addition and position of the flowers. The string was a little distracting to me at first, but after reading the title, I see they must be setting alignment for yet another plot. What an honor, what a disgrace and what a way to capture the emotion. One of my top picks  9', '2003-11-04 23:47:19.000000', NULL, 1),
(472657, 44929, 6804, '<td valign="top">I am back to this now for the third time. Great emotion, the black/white is the ideal choice for this i think. My only suggestion is to raise the crop just a little to avoid cutting his head, but I see the horizon is a bit distracting and it may not work for this shot. - nice work.</td>', 'I am back to this now for the third time. Great emotion, the black/white is the ideal choice for this i think. My only suggestion is to raise the crop just a little to avoid cutting his head, but I see the horizon is a bit distracting and it may not work for this shot. - nice work.', '2003-11-04 23:54:22.000000', NULL, 1),
(472661, 44935, 6804, '<td valign="top">I expected to see a lot more mirrors in this challenge, but I am glad to see you did this in an artistic and unusual way. I like it. The black/white is a good choice for this.</td>', 'I expected to see a lot more mirrors in this challenge, but I am glad to see you did this in an artistic and unusual way. I like it. The black/white is a good choice for this.', '2003-11-04 23:57:40.000000', NULL, 1),
(472663, 45129, 6804, '<td valign="top">This is just great, the flower makes the shot. I like it.</td>', 'This is just great, the flower makes the shot. I like it.', '2003-11-04 23:58:53.000000', NULL, 1),
(472672, 45009, 5767, '<td valign="top">The lines here are beautiful.  Excellent tones and lighting.</td>', 'The lines here are beautiful.  Excellent tones and lighting.', '2003-11-05 00:05:43.000000', NULL, 1),
(472679, 45036, 5767, '<td valign="top">Interesting lighting here - obvious symbolism, but very original display and composition!</td>', 'Interesting lighting here - obvious symbolism, but very original display and composition!', '2003-11-05 00:07:13.000000', NULL, 1),
(472681, 44957, 5767, '<td valign="top">Interesting composition and great colors.</td>', 'Interesting composition and great colors.', '2003-11-05 00:09:17.000000', NULL, 1),
(472685, 45096, 5767, '<td valign="top">Nice lines and they definitely convey a sense of an infinite path.</td>', 'Nice lines and they definitely convey a sense of an infinite path.', '2003-11-05 00:10:17.000000', NULL, 1),
(472686, 44999, 5767, '<td valign="top">Beautiful colors - nice balance of blues and yellows.</td>', 'Beautiful colors - nice balance of blues and yellows.', '2003-11-05 00:11:03.000000', NULL, 1),
(472690, 44904, 5767, '<td valign="top">Wow - what a great image and a wonderful education.  i''ve only seen individual ones of these, not their whole army.</td>', 'Wow - what a great image and a wonderful education.  i''ve only seen individual ones of these, not their whole army.', '2003-11-05 00:12:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(472694, 45138, 5767, '<td valign="top">Great patterns and color here. Beautiful image.</td>', 'Great patterns and color here. Beautiful image.', '2003-11-05 00:14:04.000000', NULL, 1),
(472700, 44899, 5767, '<td valign="top">Love it - lighting, patterns and details all work great together.</td>', 'Love it - lighting, patterns and details all work great together.', '2003-11-05 00:15:40.000000', NULL, 1),
(472704, 45176, 5767, '<td valign="top">What a fun photograph - very graphic.  Lighting, color saturation and composition are amazing.</td>', 'What a fun photograph - very graphic.  Lighting, color saturation and composition are amazing.', '2003-11-05 00:16:35.000000', NULL, 1),
(472742, 44981, 5767, '<td valign="top">Beautiful lights - the image is breathtaking.  The perspective created by the houses really adds a lot to this.</td>', 'Beautiful lights - the image is breathtaking.  The perspective created by the houses really adds a lot to this.', '2003-11-05 00:28:56.000000', NULL, 1),
(472743, 45155, 5767, '<td valign="top">My kind of image. Well done - the contrast level is just right and the repeatitive patterns work reall well here.</td>', 'My kind of image. Well done - the contrast level is just right and the repeatitive patterns work reall well here.', '2003-11-05 00:29:40.000000', NULL, 1),
(472747, 45101, 5767, '<td valign="top">Great contrast levels - nice subject matter contrast, too.  Sharp spires against fluffy clouds works great together.</td>', 'Great contrast levels - nice subject matter contrast, too.  Sharp spires against fluffy clouds works great together.', '2003-11-05 00:31:05.000000', NULL, 1),
