(478371, 44619, 9441, '<td valign="top">Awesome!!  The colors and tones are superb!  Such a cool shot...10 from me.</td>', 'Awesome!!  The colors and tones are superb!  Such a cool shot...10 from me.', '2003-11-09 23:55:44.000000', NULL, 1),
(478373, 44999, 9441, '<td valign="top">wonderful golden hues.  The concept is wonderful and the details are fantastic....I can almost feel the sand in this shot...good job!  10</td>', 'wonderful golden hues.  The concept is wonderful and the details are fantastic....I can almost feel the sand in this shot...good job!  10', '2003-11-09 23:58:07.000000', NULL, 1),
